window.docContents[109].resolve({"/Solver/#Cvc___lean----High-Level-API-for-CVC5--Solver--Defining-_LPAR_recursive_RPAR_-function-symbols--Mutually-recursive-function-symbols":{"contents":"Cvc.lean does not, currently, expose special functions for defining mutually recursive functions in its typed API. The untyped API does, which is what we present below.\n\n\n\nopen Cvc Untyped\nvariable [Ω]\n\n\n#eval Env.runIO do\n  let int ← Srt.int\n  let bool ← Srt.bool\n  let solver ← Solver.new\n  solver.setOption \"produce-models\" \"true\"\n  solver.setOption \"fmf-fun\" \"true\"\n  let even ← solver.declareFun \"even\" #[int] bool\n  let odd ← solver.declareFun \"odd\" #[int] bool\n  let n ← Term.mkBVar int \"n\"\n  let m ← Term.mkBVar int \"m\"\n  solver.defineFunsRec #[even, odd] #[#[n], #[m]] #[\n    ← smt! if n ≤ 0 then n = 0 else odd (n - 1),\n    ← smt! if m ≤ 0 then false else even (m - 1)]\n  let i ← Term.mkSymbol int \"i\"\n  smt! 3 ≤ i >>= solver.assert\n  println! \"forcing even\"\n  solver.checkSat (assuming := #[← smt! even i])\n    (ifSat := do println! \"  sat, i := {← i.getValue}\")\n  println! \"forcing odd\"\n  solver.checkSat (assuming := #[← smt! odd i])\n    (ifSat := do println! \"  sat, i := {← i.getValue}\")\n\n\nforcing even\n  sat, i := 4\nforcing odd\n  sat, i := 3\n\n\n","context":"Cvc.lean -- High-Level API for CVC5\u0009Solver\u0009Defining (recursive) function symbols","header":"5.4.1. Mutually recursive function symbols","id":"/Solver/#Cvc___lean----High-Level-API-for-CVC5--Solver--Defining-_LPAR_recursive_RPAR_-function-symbols--Mutually-recursive-function-symbols"}});